10	  const keys = Object.keys(styles);
11	  const values = keys.map(() => new Animated.Value(0));
12	  const compositions = [];
13	  const reverseCompositions = [];
14	  const animations = {};
15	  keys.forEach((key, index) => {
16	    const value = values[index];
17	    // biome-ignore lint/style/noNonNullAssertion: Explicitly cast as string | number array due to interpolation limits. This is safe because all entry values are extensions of string | number values, but with specific formatting like `${number}deg`
18	    const definition = styles[key];
19	    const animation = value.interpolate({
20	      inputRange: definition.map((_, i) => i),
21	      outputRange: definition
22	    });
23	    const composition = Animated.timing(value, {
24	      toValue: definition.length - 1,
25	      duration,
26	      useNativeDriver: !!native,
27	      easing,
28	      isInteraction
29	    });
30	    const reverseComposition = Animated.timing(value, {
31	      toValue: 0,
32	      duration,
33	      useNativeDriver: !!native,
34	      easing,
35	      isInteraction
36	    });
