118	  const {
119	    animations,
120	    reverseCompositions,
121	    compositions
122	  } = processStyles(styles, config || {});
123	  const trigger = createStaggerComposition(compositions, config.stagger || 200);
124	  const reverseTrigger = createStaggerComposition(reverseCompositions, config.stagger || 200);
125	  return {
126	    ...getAnimationTriggers(trigger, reverseTrigger),
