132	function createSequenceComposition(compositions) {
133	  return {
134	    start: callback => {
135	      function startComposition(index) {
136	        const composition = compositions[index];
137	        composition.start(({
138	          finished
139	        }) => {
140	          if (finished) {
141	            const nextIndex = index + 1;
142	            if (nextIndex < compositions.length) {
143	              startComposition(nextIndex);
144	            } else {
145	              callback?.({
146	                finished: true
147	              });
148	            }
149	          }
150	        });
151	      }
152	      startComposition(0);
153	    },
154	    stop: () => {
155	      for (const composition of compositions) composition.stop();
156	    },
157	    reset: () => {
158	      for (const composition of compositions) composition.reset();
159	    }
160	  };
161	}
