163	/** This will animate the passed in styles in sequence.
164	 * Example: if you define opacity and top styles, this will start the opacity animation and then start the top animation when the opacity animation finishes. */
165	export function animateSequence(styles, config) {
166	  const {
167	    animations,
168	    reverseCompositions,
169	    compositions
170	  } = processStyles(styles, config || {});
171	  const trigger = createSequenceComposition(compositions);
172	  const reverseTrigger = createSequenceComposition(reverseCompositions);
173	  return {
174	    ...getAnimationTriggers(trigger, reverseTrigger),
175	    forward: trigger,
176	    backward: reverseTrigger,
177	    animations
178	  };
179	}
180	export function createAnimationTimeline(timeline) {
181	  const times = Object.keys(timeline).map(ms => Number(ms));
182	  const lastTime = times[times.length - 1];
183	  const reverseTimes = times.reverse();
184	  const compositions = [];
185	  const reverseCompositions = [];
186	  for (const ms of times) {
187	    const elements = timeline[ms];
188	    const trigger = Animated.parallel(elements.map(e => e.forward));
189	    compositions.push(!ms ? trigger : createSequenceComposition([Animated.delay(ms), trigger]));
190	  }
191	  for (const ms of reverseTimes) {
192	    const delay = lastTime - ms;
193	    const elements = timeline[ms];
194	    const trigger = Animated.parallel(elements.map(e => e.backward));
195	    reverseCompositions.push(!delay ? trigger : createSequenceComposition([Animated.delay(delay), trigger]));
196	  }
197	  const forward = Animated.parallel(compositions.flat());
198	  const backward = Animated.parallel(reverseCompositions.flat());
199	  return {
200	    start: forward.start,
201	    reverse: backward.start,
202	    reset: forward.reset
203	  };
204	}
205	export function loopAnimation(animation) {
206	  const restart = () => {
207	    animation.reset();
208	    animation.start(restart);
209	  };
210	  const start = () => animation.start(restart);
211	  return {
212	    ...animation,
213	    start
214	  };
215	}
